import Model from 'flarum/common/Model';
/**
 * A tour, as the admin area edits it. The forum reads a narrower payload of
 * its own; see `forum/loadTours`.
 */
export default class Tour extends Model {
  key() {
    return Model.attribute('key').call(this);
  }
  title() {
    return Model.attribute('title').call(this);
  }
  isEnabled() {
    return Model.attribute('isEnabled').call(this);
  }

  /** 'auto' starts itself, 'manual' waits to be launched by the member. */
  startMode() {
    return Model.attribute('startMode').call(this);
  }

  /** A Flarum route name, or null to run wherever the member is. */
  route() {
    return Model.attribute('route').call(this);
  }
  devices() {
    return Model.attribute('devices').call(this);
  }

  /** Group ids that may see it. Null or empty means everybody. */
  groupIds() {
    return Model.attribute('groupIds').call(this);
  }
  maxAccountAgeDays() {
    return Model.attribute('maxAccountAgeDays').call(this);
  }
  position() {
    return Model.attribute('position').call(this);
  }
  stepCount() {
    return Model.attribute('stepCount').call(this);
  }
  steps() {
    return Model.hasMany('steps').call(this);
  }
}
flarum.reg.add('datlechin-simple-tour-guide', 'common/models/Tour', Tour);